documentations-gallery--gallery-example.snippet:
import { Component } from '@angular/core';
import { Gallery } from 'ng-gallery';
import { GalleryModule } from 'ng-gallery';
import { NgOptimizedImage } from '@angular/common';

@Component({
  selector: 'app-demo',
  imports: [Gallery, GalleryModule, NgOptimizedImage],
  template: `
    <gallery
        [items]="items"
        [loop]="loop"
        [gap]="gap"
        [itemsPerView]="itemsPerView"
        [itemSize]="itemSize"
        [steps]="steps"
        [snapAlign]="snapAlign"
        [forceSnap]="forceSnap"
        [resizeDebounceTime]="resizeDebounceTime"
        [orientation]="orientation"
        [scrollDuration]="scrollDuration"
        [scrollBehavior]="scrollBehavior"
        [disableScroll]="disableScroll"
        [disableMouseScroll]="disableMouseScroll"
        (activeIndexChange)="activeIndexChange($event)"
        (anchorIndexChange)="anchorIndexChange($event)">
        <img
            *galleryItemDef="let item"
            galleryImage
            [src]="item.src"
            [alt]="item.alt" />
        <gallery-nav/>
    </gallery>`,
})
export class DemoComponent {
  loop = false;
  snapAlign = 'center';
  forceSnap = false;
  disableScroll = false;
  disableMouseScroll = false;
  itemsPerView = 1;
  gap = 1;
  steps = 1;
  itemSize = null;
  orientation = 'horizontal';
  scrollBehavior = 'smooth';
  scrollDuration = 468;
  resizeDebounceTime = 468;
}

