documentations-gallery--auto-height-exam.snippet:
import { Component } from '@angular/core';
import { Gallery } from 'ng-gallery';
import { GalleryModule } from 'ng-gallery';
import { NgOptimizedImage } from '@angular/common';

@Component({
  selector: 'app-demo',
  imports: [Gallery, GalleryModule, NgOptimizedImage],
  template: `
    <gallery class="gallery-example" [items]="items" autoHeight>
        <div
            *galleryItemDef="let item; index as i"
            class="slide"
            [style.height.px]="i % 2 == 1 ? 150 : 200">
            <span>{{ i + 1 }}</span>
        </div>
        <gallery-nav outside/>
    </gallery>`,
})
export class DemoComponent {}
